() => {
  const out = {};
  const body = getComputedStyle(document.body);
  out.body = {bg: body.backgroundColor, color: body.color, font: body.fontFamily, size: body.fontSize};
  // menu bar
  const nav = document.querySelector('nav') || document.querySelector('[aria-label="Main Menu"]');
  if (nav) { const s = getComputedStyle(nav); out.nav = {bg:s.backgroundColor, color:s.color, h:nav.getBoundingClientRect().height}; }
  // top buttons
  const btns = document.querySelectorAll('button');
  out.sampleBtn = btns.length ? (()=>{const b=btns[0]; const s=getComputedStyle(b); return {bg:s.backgroundColor,color:s.color,border:s.border,radius:s.borderRadius,padding:s.padding};})() : null;
  out.title = document.title;
  out.bodyChildren = [...document.body.children].map(c=>c.tagName+'#'+(c.id||'')+'.'+(c.className||''));
  return out;
}

