() => {
  const r = (el) => { if(!el) return null; const b=el.getBoundingClientRect(); return {x:Math.round(b.x),y:Math.round(b.y),w:Math.round(b.width),h:Math.round(b.height)}; };
  const out={};
  const sb = document.querySelector('.sidebar_left');
  if(sb) out.leftItems = [...sb.children].map(c=>({tag:c.tagName,cls:c.className,title:c.getAttribute('title'),rect:r(c)}));
  // top toolbar sits y 30..75
  const between = [...document.querySelectorAll('.wrapper *')].filter(e=>{const b=e.getBoundingClientRect(); return b.top>=29 && b.bottom<=76 && b.width>0;});
  out.topRow = between.slice(0,20).map(e=>({tag:e.tagName,cls:e.className,id:e.id,txt:(e.textContent||'').slice(0,20),rect:r(e)}));
  const sr = document.querySelector('.sidebar_right');
  if(sr) out.rightSections = [...sr.children].map(c=>({cls:c.className,rect:r(c),head:(c.querySelector('h1,h2,h3,span')||{}).textContent}));
  return out;
}

