  const h = document.querySelector('.block h2, .block .header, .block > span, .block > div');
  const out={};
  const info = (e) => { if(!e) return null; const c=getComputedStyle(e); const b=e.getBoundingClientRect(); return {tag:e.tagName,cls:e.className,bg:c.backgroundColor,color:c.color,pad:c.padding,fs:c.fontSize,fw:c.fontWeight,h:Math.round(b.height),borderBottom:c.borderBottom,radius:c.borderTopLeftRadius}; };
  out.first = info(h);
  // the preview block structure
  const pb = document.querySelector('.preview.block');
  if(pb) out.previewChildren = [...pb.children].map(c=>({tag:c.tagName,cls:c.className,...info(c)}));
  const cb = document.querySelector('.colors.block');
  if(cb) out.colorsChildren = [...cb.children].map(c=>({tag:c.tagName,cls:c.className,info:info(c)}));
  return out;
}

