/* miniPaint-style image editor — original implementation */

:root {
  --mp-bg: #666d6f;
  --mp-text: #f4f3f3;
  --mp-menu-bg: #222222;
  --mp-bar-bg: #323a3c;
  --mp-side-bg: #2f3739;
  --mp-block-bg: #464d4f;
  --mp-header-bg: #373d3f;
  --mp-input-bg: #2f3739;
  --mp-input-border: #0f0f0f;
  --mp-accent: #adecab;
  --mp-highlight: #d4f995;
  --mp-active: #658b65;
  --mp-info: #90c5ee;
  --mp-dark: #111;
  --mp-sep: #555555;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--mp-bg);
  color: var(--mp-text);
  font-family: Arial, Helvetica, sans-serif;
  font-size: 13px;
  overflow: hidden;
}

button {
  font-family: inherit;
  font-size: inherit;
  color: inherit;
  cursor: pointer;
}

input,
select,
textarea {
  font-family: inherit;
  font-size: 13px;
}

.mp-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
::-webkit-scrollbar-track {
  background: #3a4143;
}
::-webkit-scrollbar-thumb {
  background: #555d5f;
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: #6b7476;
}

.mp-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 10px;
  border-radius: 2px;
  background: #fff;
  outline: none;
}
.mp-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #ddd;
  border: 1px solid #333;
  cursor: pointer;
}
.mp-range::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #ddd;
  border: 1px solid #333;
  cursor: pointer;
}

