    const tools = document.querySelectorAll('.mp-tool').length;
    const blocks = [...document.querySelectorAll('.mp-block-heading')].map(h=>h.textContent.trim().replace(/[▲▼]/g,'').trim());
    const c = document.querySelector('.mp-canvas-stage canvas');
    return { menus, tools, blocks, canvas: {w:c.width,h:c.height} };
  });

  // 2. ZOOM changes display scale, not doc size
  const before = await page.evaluate(() => { const c=document.querySelector('.mp-canvas-stage canvas'); return {cw:c.width, doc:document.body.innerText.match(/(\d+) x (\d+) px/).slice(1,3).join('x')}; });
  await page.locator('.mp-mini-btn').first().click();
  await page.locator('.mp-mini-btn').first().click();
  await page.waitForTimeout(300);
  const after = await page.evaluate(() => { const c=document.querySelector('.mp-canvas-stage canvas'); return {cw:c.width, doc:document.body.innerText.match(/(\d+) x (\d+) px/).slice(1,3).join('x')}; });
  log.zoom = { before, after };

  // 3. SAVE project -> nonempty structured document
  await page.evaluate(() => { window.__cap=null; HTMLAnchorElement.prototype.click = function(){ window.__cap={download:this.download, href:String(this.href)}; }; });
  await page.locator('.mp-menu-title:has-text("File")').click();
