  await page.waitForTimeout(150);
  await page.locator('.mp-dialog-btn:has-text("Ok")').click();
  await page.waitForTimeout(300);
  log.save = await page.evaluate(() => {
    const json = decodeURIComponent((window.__cap?.href||'').split(',').slice(1).join(','));
    const p = JSON.parse(json);
    return { download: window.__cap?.download, chars: json.length, hasInfo: !!p.info, layers: p.layers.length, keys: Object.keys(p) };
  });

  // 4. NEW document still works
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("New")').first().click();
  await page.waitForTimeout(200);
  const dlg = await page.locator('.mp-dialog').count();
  await page.locator('.mp-dialog-btn:has-text("Cancel")').click();
  log.newDialog = dlg;

  // 5. QUICK SAVE
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("Quick Save")').first().click();
  await page.waitForTimeout(200);
  log.quickSave = await page.evaluate(() => { const r = localStorage.getItem('quicksave_data'); return r ? {len:r.length, valid: !!JSON.parse(r).info} : null; });

  return JSON.stringify({ errs, log }, null, 1);
}

