async (page) => {
  await page.goto('http://localhost:4173');
  await page.waitForTimeout(600);
  const state = () => page.evaluate(() => {
    const c = document.querySelector('.mp-canvas-stage canvas');
    const r = c.getBoundingClientRect();
    const sz = document.body.innerText.match(/Size:\s*(\d+) x (\d+) px/);
    return { attr:[c.width,c.height], css:[Math.round(r.width),Math.round(r.height)], infoSize: sz?sz[1]+'x'+sz[2]:null };
  });
  const out = { initial: await state() };
  // zoom out twice
  await page.locator('.mp-mini-btn').first().click();
  await page.locator('.mp-mini-btn').first().click();
  await page.waitForTimeout(300);
  out.afterZoomOut = await state();
  // new doc 800x600 via dialog with explicit inputs
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("New")').first().click();
  await page.waitForTimeout(250);
  await page.evaluate(() => {
    const w = document.querySelector('input[aria-label="Width:"]');
    const h = document.querySelector('input[aria-label="Height:"]');
    const setV = (el,v)=>{ const setter=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set; setter.call(el,v); el.dispatchEvent(new Event('input',{bubbles:true})); };
    setV(w, 800); setV(h, 600);
  });
  await page.waitForTimeout(200);
  await page.locator('.mp-dialog-btn:has-text("Ok")').click();
  await page.waitForTimeout(500);
  out.afterNew = await state();
  return JSON.stringify(out, null, 1);
}

