/* ---- composite ---- */
/* The document is always composited at its intrinsic size, so the canvas
   backing store equals the document dimensions. Zoom is applied purely as a
   CSS scale by the view, so changing zoom never alters the document. */
const composite = useCallback(() => {
  const disp = displayRef.current;
  if (!disp) return;
  if (disp.width !== W || disp.height !== H) {
    disp.width = W;
    disp.height = H;
  }
  const ctx = disp.getContext("2d", { willReadFrequently: true })!;
  ctx.clearRect(0, 0, W, H);
  for (const [, rt] of layerRefs.current) {
    if (!rt.visible) continue;
    ctx.globalAlpha = Math.max(0, Math.min(1, rt.opacity / 100));
    ctx.drawImage(rt.canvas, rt.x, rt.y);
  }
  ctx.globalAlpha = 1;
}, [W, H]);

/** keep the display backing store equal to the document dimensions */
const resizeDisplay = useCallback((docW: number, docH: number) => {
  const disp = displayRef.current;
  if (!disp) return;
