async (page) => {
  const errs = [];
  page.on('console', m => { if (m.type()==='error') errs.push(m.text()); });
  page.on('pageerror', e => errs.push('pageerror: '+e.message));
  await page.goto('http://localhost:4173');
  await page.waitForTimeout(500);
  const state = () => page.evaluate(() => {
    const c = document.querySelector('.mp-canvas-stage canvas');
    const r = c.getBoundingClientRect();
    const sz = document.body.innerText.match(/Size:\s*(\d+) x (\d+) px/);
    return { intrinsic:[c.width,c.height], display:[Math.round(r.width),Math.round(r.height)],
             cssW: getComputedStyle(c).width, infoSize: sz?sz[1]+'x'+sz[2]:null };
  });
  const out = { initial: await state() };
  // ZOOM: click "-" twice
  await page.locator('.mp-mini-btn').first().click();
  await page.locator('.mp-mini-btn').first().click();
  await page.waitForTimeout(300);
  out.afterZoomOut = await state();
  // reset zoom via "100%" button
  await page.locator('.mp-mini-btn').nth(1).click();
  await page.waitForTimeout(200);
  // NEW document 800x600
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("New")').first().click();
  await page.waitForTimeout(250);
  await page.evaluate(() => { const r=[...document.querySelectorAll('.mp-dialog input[type=radio]')].find(x=>x.value==='800x600'); if(r) r.click(); });
  await page.waitForTimeout(200);
  await page.locator('.mp-dialog-btn:has-text("Ok")').click();
  await page.waitForTimeout(400);
  out.afterNew = await state();
  return JSON.stringify({ errs, out }, null, 1);
}

