/** zoom percentage at which `w x h` just fits the visible canvas area */
const fitZoomFor = useCallback((w: number, h: number) => {
  const area = document.querySelector(".mp-canvas-area");
  const rect = area?.getBoundingClientRect();
  const availW = rect && rect.width > 0 ? rect.width - 10 : window.innerWidth - 260;
  const availH = rect && rect.height > 0 ? rect.height - 10 : window.innerHeight - 120;
  const z = Math.min(availW / w, availH / h, 1);
  return Math.max(0.05, Math.round(z * 100) / 100) * 100;
}, []);

